import { describe, expect, it } from "vitest";
import {
  PLAN_LIMITS,
  PLAN_ORDER,
  UNLIMITED,
  getLimit,
  getPlanLimits,
  planAtLeast,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { PLAN_IDS } from "@/types/billing";
import type { LimitedResource, PlanId } from "@/types/billing";

const NUMERIC_RESOURCES: LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

describe("plan limits", () => {
  it("declares limits for every plan id, with no gaps", () => {
    for (const plan of PLAN_IDS) {
      expect(getPlanLimits(plan).plan).toBe(plan);
    }
    expect(PLAN_ORDER).toEqual([...PLAN_IDS]);
  });

  it("never lowers a quota as the plan gets richer", () => {
    for (const resource of NUMERIC_RESOURCES) {
      let previous = -1;
      for (const plan of PLAN_ORDER) {
        const limit = getLimit(plan, resource);
        expect(limit).toBeGreaterThanOrEqual(previous);
        previous = limit;
      }
    }
  });

  it("treats enterprise seats as unlimited", () => {
    expect(PLAN_LIMITS.enterprise.seats).toBe(UNLIMITED);
    expect(wouldExceedLimit("enterprise", "seats", 1_000_000, 1)).toBe(false);
  });

  it("wouldExceedLimit compares used + requested against the quota", () => {
    expect(wouldExceedLimit("free", "seats", 2, 1)).toBe(false);
    expect(wouldExceedLimit("free", "seats", 3, 1)).toBe(true);
    expect(wouldExceedLimit("free", "projects", 1)).toBe(false);
    expect(wouldExceedLimit("free", "projects", 2)).toBe(true);
  });

  it("planAtLeast orders plans cheapest to richest", () => {
    expect(planAtLeast("growth", "starter")).toBe(true);
    expect(planAtLeast("starter", "growth")).toBe(false);
    expect(planAtLeast("free", "free")).toBe(true);
  });

  it("grows the included flag set monotonically with the plan", () => {
    let previous = 0;
    for (const plan of PLAN_ORDER as PlanId[]) {
      const count = getPlanLimits(plan).includedFlags.length;
      expect(count).toBeGreaterThanOrEqual(previous);
      previous = count;
    }
  });

  it("gives the free plan no webhooks", () => {
    expect(getLimit("free", "webhooks")).toBe(0);
    expect(wouldExceedLimit("free", "webhooks", 0, 1)).toBe(true);
  });
});
/** Plan ordering, `wouldExceedLimit` and the enterprise unlimited sentinel. */
import { describe, expect, it } from "vitest";
import {
  PLAN_LIMITS,
  PLAN_ORDER,
  UNLIMITED,
  getLimit,
  getPlanLimits,
  planAtLeast,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { PLAN_IDS, type LimitedResource } from "@/types/billing";

const RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

describe("config/plan-limits", () => {
  it("declares limits for every plan id", () => {
    for (const plan of PLAN_IDS) {
      expect(getPlanLimits(plan).plan).toBe(plan);
    }
    expect([...PLAN_ORDER].sort()).toEqual([...PLAN_IDS].sort());
  });

  it("never shrinks a quota as the plan gets richer", () => {
    for (const resource of RESOURCES) {
      for (let i = 1; i < PLAN_ORDER.length; i += 1) {
        const previous = PLAN_ORDER[i - 1];
        const current = PLAN_ORDER[i];
        if (!previous || !current) continue;
        expect(
          getLimit(current, resource),
          `${resource}: ${current} vs ${previous}`,
        ).toBeGreaterThanOrEqual(getLimit(previous, resource));
      }
    }
  });

  it("orders plans cheapest to richest", () => {
    expect(planAtLeast("growth", "starter")).toBe(true);
    expect(planAtLeast("starter", "growth")).toBe(false);
    expect(planAtLeast("free", "free")).toBe(true);
    expect(planAtLeast("enterprise", "free")).toBe(true);
  });

  it("uses Infinity as the unlimited sentinel on enterprise", () => {
    expect(PLAN_LIMITS.enterprise.seats).toBe(UNLIMITED);
    expect(Number.isFinite(PLAN_LIMITS.enterprise.projects)).toBe(false);
    expect(Number.isFinite(PLAN_LIMITS.free.projects)).toBe(true);
  });

  it("never exceeds an unlimited quota", () => {
    expect(wouldExceedLimit("enterprise", "seats", 1_000_000)).toBe(false);
    expect(wouldExceedLimit("enterprise", "projects", 10_000, 10_000)).toBe(false);
  });

  it("refuses the request that would cross the boundary, not the one that reaches it", () => {
    // free allows 3 seats
    expect(wouldExceedLimit("free", "seats", 2)).toBe(false);
    expect(wouldExceedLimit("free", "seats", 3)).toBe(true);
    expect(wouldExceedLimit("free", "seats", 0, 3)).toBe(false);
    expect(wouldExceedLimit("free", "seats", 0, 4)).toBe(true);
  });

  it("blocks webhooks entirely on the free plan", () => {
    expect(getLimit("free", "webhooks")).toBe(0);
    expect(wouldExceedLimit("free", "webhooks", 0)).toBe(true);
    expect(wouldExceedLimit("starter", "webhooks", 0)).toBe(false);
  });

  it("reads a single quota without destructuring PlanLimits", () => {
    for (const resource of RESOURCES) {
      expect(getLimit("growth", resource)).toBe(PLAN_LIMITS.growth[resource]);
    }
  });

  it("includes strictly more flags on each richer plan", () => {
    for (let i = 1; i < PLAN_ORDER.length; i += 1) {
      const previous = PLAN_ORDER[i - 1];
      const current = PLAN_ORDER[i];
      if (!previous || !current) continue;
      const richer = new Set(getPlanLimits(current).includedFlags);
      for (const flag of getPlanLimits(previous).includedFlags) {
        expect(richer.has(flag), `${current} should include ${flag}`).toBe(true);
      }
    }
  });

  it("prices seats monotonically, starting free", () => {
    expect(PLAN_LIMITS.free.priceCentsPerSeatMonthly).toBe(0);
    for (let i = 1; i < PLAN_ORDER.length; i += 1) {
      const previous = PLAN_ORDER[i - 1];
      const current = PLAN_ORDER[i];
      if (!previous || !current) continue;
      expect(
        getPlanLimits(current).priceCentsPerSeatMonthly,
      ).toBeGreaterThan(getPlanLimits(previous).priceCentsPerSeatMonthly);
    }
  });
});
/**
 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
 */
import {
  getLimit,
  getPlanLimits,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, billingResource, requireFound } from "./_support";
import type {
  CancelSubscriptionInput,
  ChangePlanInput,
  UpdateSeatsInput,
} from "@/schemas/billing";
import type {
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function getBillingSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<BillingSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(orgId),
    "Subscription",
    orgId,
  );

  const checks = await Promise.all(
    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
  );

  const limits = getPlanLimits(subscription.plan);

  return {
    orgId,
    subscription,
    checks,
    upcomingInvoiceCents:
      limits.priceCentsPerSeatMonthly *
      subscription.seats *
      (subscription.interval === "annual" ? 12 : 1),
  };
}

/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}
import { z } from "zod";
import type { PlanId } from "@/types/billing";
import { orgIdSchema } from "./common";

export const planIdSchema = z.enum(["free", "starter", "growth", "enterprise"]);

export const billingIntervalSchema = z.enum(["monthly", "annual"]);

export const subscriptionStatusSchema = z.enum([
  "trialing",
  "active",
  "past_due",
  "canceled",
]);

export const limitedResourceSchema = z.enum([
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
]);

export const changePlanSchema = z.object({
  orgId: orgIdSchema,
  plan: planIdSchema,
  interval: billingIntervalSchema.default("monthly"),
});

export const updateSeatsSchema = z.object({
  orgId: orgIdSchema,
  seats: z.number().int().min(1).max(10_000),
});

export const cancelSubscriptionSchema = z.object({
  orgId: orgIdSchema,
  reason: z.string().max(500).optional(),
  cancelImmediately: z.boolean().default(false),
});

const _planParity: PlanId = "growth" satisfies z.infer<typeof planIdSchema>;
void _planParity;

export type ChangePlanInput = z.infer<typeof changePlanSchema>;
export type UpdateSeatsInput = z.infer<typeof updateSeatsSchema>;
export type CancelSubscriptionInput = z.infer<typeof cancelSubscriptionSchema>;

