/**
 * Calendar arithmetic for recurring issues.
 *
 * A recurrence works in whole calendar days written `YYYY-MM-DD`, counted in
 * the rule's own IANA time zone. Days are plain calendar values here — never
 * instants — so daylight-saving shifts cannot move an occurrence to another
 * day; the zone only decides which calendar day it currently is.
 */
import type { RecurringIssue } from "@/types/recurring-issue";

const DAY_MS = 86_400_000;
const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Parses a `YYYY-MM-DD` day to its UTC midnight; `null` unless it is a real date. */
function parseCalendarDate(value: string): Date | null {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return null;

  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
  // `setUTCFullYear` rather than `Date.UTC`, which maps years 0-99 to 19xx.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);

  const real =
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day;
  return real ? date : null;
}

function formatCalendarDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** ISO weekday of a UTC-midnight date: 1 = Monday … 7 = Sunday. */
function isoWeekday(date: Date): number {
  return date.getUTCDay() === 0 ? 7 : date.getUTCDay();
}

/** True for a real `YYYY-MM-DD` calendar day — `2026-02-30` is not one. */
export function isCalendarDate(value: string): boolean {
  return parseCalendarDate(value) !== null;
}

/**
 * True for an IANA zone name the runtime knows. Fixed-offset spellings such as
 * `+02:00` are accepted by `Intl` but are not zone names, so they are refused.
 */
export function isKnownTimeZone(value: string): boolean {
  if (value === "" || value.startsWith("+") || value.startsWith("-")) {
    return false;
  }
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

const localDayFormats = new Map<string, Intl.DateTimeFormat>();

/** The calendar day it is at `instant` on the wall clocks of `timeZone`. */
function localCalendarDate(instant: Date, timeZone: string): string {
  let format = localDayFormats.get(timeZone);
  if (format === undefined) {
    format = new Intl.DateTimeFormat("en-US", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    localDayFormats.set(timeZone, format);
  }

  const part = (type: "year" | "month" | "day"): string =>
    format.formatToParts(instant).find((entry) => entry.type === type)?.value ?? "";

  return `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
}

/**
 * The latest occurrence day of `rule` that has started by `now`, or `null`.
 *
 * A daily rule occurs on every day from `startsOn` on; a weekly one on every
 * such day whose ISO weekday is `weekday`. Day D has started once the wall
 * clock in the rule's zone has reached 00:00 on D, which is the same as D not
 * being later than the zone's current calendar day.
 */
export function latestOccurrenceOn(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  const startsOn = parseCalendarDate(rule.startsOn);
  const today = parseCalendarDate(localCalendarDate(now, rule.timezone));
  if (startsOn === null || today === null) {
    throw new RangeError(`Cannot place ${rule.startsOn} in ${rule.timezone}`);
  }

  let latest = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) {
      throw new RangeError("A weekly recurrence needs a weekday");
    }
    const daysBack = (isoWeekday(today) - rule.weekday + 7) % 7;
    latest = new Date(today.getTime() - daysBack * DAY_MS);
  }

  return latest.getTime() < startsOn.getTime() ? null : formatCalendarDate(latest);
}

