/**
 * Recurring-issue rules: authorization, the plan's rule quota and pausing. The
 * background job that files the issues lives in `jobs/recurring-issue-job.ts`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived
 */
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { checkLimit } from "./billing-service";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

/**
 * Creating a rule takes the same gates as creating an issue in its project —
 * tenant scope, a live project, `issue:create` — plus two of its own: the
 * assignee has to be an active member, and the plan's rule quota must have
 * room (paused rules count against it).
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const rule = createRecurringIssueSchema.parse(input);

  assertOrgScope(actor, rule.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (rule.assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error(`User ${rule.assigneeId} is not an active member`);
    }
  }

  const { plan, limit, exceeded } = await checkLimit(
    rule.orgId,
    "recurringIssues",
  );
  const created = exceeded
    ? null
    : await recurringIssueRepo.insertRecurringIssueWithinLimit(
        rule,
        actor.userId,
        limit,
      );
  if (created === null) {
    throw new Error(
      `Plan ${plan} allows ${limit} recurring issues in this organization`,
    );
  }

  return created;
}

/** Pausing is gated like filing an issue in the rule's project would be. */
export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringIssueRepo.findRecurringIssueById(
      input.orgId,
      input.recurringIssueId,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringIssueRepo.setPaused(rule.orgId, rule.id, input.paused);
}

/** Every rule of the organization, oldest first. */
export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}

