/**
 * Files an ordinary issue for the latest occurrence of every active recurring-issue rule.
 *
 * Must call (do not reimplement): createIssue, latestOccurrenceOn, isArchived
 */
import { createLogger } from "@/lib/logger";
import { PermissionDeniedError } from "@/lib/permissions";
import { latestOccurrenceOn } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { UserId } from "@/types/common";
import type { Actor, Member } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/** Runs are strictly serial: a second run waits, then sees what the first filed. */
let previousRun: Promise<unknown> = Promise.resolve();

/**
 * Creates at most one issue per rule, always for the latest occurrence that
 * has started by `now`; occurrences missed while the job was not running are
 * never back-filled. The issue is filed through `createIssue` as the rule's
 * creator, so it passes the same checks and publishes the same events as one
 * that person created by hand. `processed` counts the issues created.
 */
export function runRecurringIssueJob(now: Date): Promise<JobResult> {
  const run = previousRun.then(() => sweep(now));
  previousRun = run.catch(() => undefined);
  return run;
}

function sweep(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const outcome = await fileOccurrence(rule, now);
        if (outcome === "created") result.processed += 1;
        if (outcome === "refused") result.failed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to process recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

type Outcome = "created" | "idle" | "refused";

async function fileOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<Outcome> {
  const occurrence = latestOccurrenceOn(rule, now);
  if (occurrence === null) return "idle";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "idle";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) return "refused";
  // Left untouched, so the first run after a restore files the then-latest day.
  if (isArchived(project)) return "idle";

  const creator = await activeMember(rule, rule.createdBy);
  if (creator === null) return pause(rule);

  const actor: Actor = {
    userId: creator.userId,
    orgId: rule.orgId,
    role: creator.role,
  };
  const assignee =
    rule.assigneeId === null ? null : await activeMember(rule, rule.assigneeId);

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId: assignee?.userId ?? null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    // The creator's role no longer allows it: stop filing for them.
    if (error instanceof PermissionDeniedError) return pause(rule);
    // Anything else (e.g. the project's issue quota) may pass by the next run.
    logger.warn("recurring issue refused", {
      recurringIssueId: rule.id,
      reason: error instanceof Error ? error.message : String(error),
    });
    return "refused";
  }

  await recurringIssueRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return "created";
}

async function activeMember(
  rule: RecurringIssue,
  userId: UserId,
): Promise<Member | null> {
  const member = await memberRepo.findMember(rule.orgId, userId);
  return member !== null && member.status === "active" ? member : null;
}

async function pause(rule: RecurringIssue): Promise<Outcome> {
  await recurringIssueRepo.setPaused(rule.orgId, rule.id, true);
  logger.warn("recurring issue paused: its creator can no longer file issues", {
    recurringIssueId: rule.id,
  });
  return "idle";
}

