import { describe, expect, it } from "vitest";
import {
  isCalendarDate,
  isKnownTimeZone,
  latestOccurrenceOn,
} from "@/lib/recurrence";

const daily = (timezone: string, startsOn: string) =>
  ({ cadence: "daily", weekday: null, timezone, startsOn }) as const;

const weekly = (timezone: string, startsOn: string, weekday: number) =>
  ({ cadence: "weekly", weekday, timezone, startsOn }) as const;

describe("lib/recurrence", () => {
  it("accepts only real calendar dates", () => {
    expect(isCalendarDate("2026-03-05")).toBe(true);
    expect(isCalendarDate("2028-02-29")).toBe(true);
    expect(isCalendarDate("2026-02-29")).toBe(false);
    expect(isCalendarDate("2026-02-30")).toBe(false);
    expect(isCalendarDate("2026-13-01")).toBe(false);
    expect(isCalendarDate("2026-3-5")).toBe(false);
    expect(isCalendarDate("2026-03-05T00:00:00Z")).toBe(false);
  });

  it("accepts IANA zone names and refuses everything else", () => {
    expect(isKnownTimeZone("UTC")).toBe(true);
    expect(isKnownTimeZone("Europe/Berlin")).toBe(true);
    expect(isKnownTimeZone("America/Argentina/Buenos_Aires")).toBe(true);
    expect(isKnownTimeZone("Mars/Olympus_Mons")).toBe(false);
    expect(isKnownTimeZone("")).toBe(false);
    expect(isKnownTimeZone("+02:00")).toBe(false);
  });

  it("finds no occurrence before the rule starts", () => {
    const rule = daily("UTC", "2026-03-10");
    expect(latestOccurrenceOn(rule, new Date("2026-03-09T23:59:59Z"))).toBeNull();
    expect(latestOccurrenceOn(rule, new Date("2026-03-10T00:00:00Z"))).toBe(
      "2026-03-10",
    );
  });

  it("takes the current calendar day of the rule's zone for a daily rule", () => {
    const rule = daily("Pacific/Auckland", "2026-01-01");
    // 12:30 UTC on the 4th is 01:30 on the 5th in Auckland (UTC+13 in March).
    expect(latestOccurrenceOn(rule, new Date("2026-03-04T12:30:00Z"))).toBe(
      "2026-03-05",
    );
    expect(latestOccurrenceOn(rule, new Date("2026-03-04T10:59:59Z"))).toBe(
      "2026-03-04",
    );
  });

  it("starts a day at local midnight across a spring-forward change", () => {
    const rule = daily("America/New_York", "2026-01-01");
    // Clocks jump 02:00 → 03:00 on 8 March 2026; midnight is still EST (UTC-5).
    expect(latestOccurrenceOn(rule, new Date("2026-03-08T04:59:59Z"))).toBe(
      "2026-03-07",
    );
    expect(latestOccurrenceOn(rule, new Date("2026-03-08T05:00:00Z"))).toBe(
      "2026-03-08",
    );
    // 9 March begins at 00:00 EDT (UTC-4) = 04:00 UTC, one hour earlier in UTC.
    expect(latestOccurrenceOn(rule, new Date("2026-03-09T03:59:59Z"))).toBe(
      "2026-03-08",
    );
    expect(latestOccurrenceOn(rule, new Date("2026-03-09T04:00:00Z"))).toBe(
      "2026-03-09",
    );
  });

  it("copes with the 25-hour day of a fall-back change", () => {
    const rule = daily("America/New_York", "2026-01-01");
    // 1 November 2026 starts at 00:00 EDT = 04:00 UTC; 2 November at 05:00 UTC.
    expect(latestOccurrenceOn(rule, new Date("2026-11-01T03:59:59Z"))).toBe(
      "2026-10-31",
    );
    expect(latestOccurrenceOn(rule, new Date("2026-11-01T04:00:00Z"))).toBe(
      "2026-11-01",
    );
    expect(latestOccurrenceOn(rule, new Date("2026-11-02T04:59:59Z"))).toBe(
      "2026-11-01",
    );
    expect(latestOccurrenceOn(rule, new Date("2026-11-02T05:00:00Z"))).toBe(
      "2026-11-02",
    );
  });

  it("takes the latest matching ISO weekday for a weekly rule", () => {
    // 2026-03-05 is a Thursday; 2026-03-02 the Monday before it.
    const thursday = new Date("2026-03-05T12:00:00Z");
    expect(latestOccurrenceOn(weekly("UTC", "2026-01-01", 1), thursday)).toBe(
      "2026-03-02",
    );
    expect(latestOccurrenceOn(weekly("UTC", "2026-01-01", 4), thursday)).toBe(
      "2026-03-05",
    );
    expect(latestOccurrenceOn(weekly("UTC", "2026-01-01", 7), thursday)).toBe(
      "2026-03-01",
    );
  });

  it("counts a weekly rule's start day, but not the days before it", () => {
    // Started on Sunday 1 March; the Monday before it does not count.
    expect(
      latestOccurrenceOn(weekly("UTC", "2026-03-01", 1), new Date("2026-03-01T09:00:00Z")),
    ).toBeNull();
    expect(
      latestOccurrenceOn(weekly("UTC", "2026-03-01", 7), new Date("2026-03-01T09:00:00Z")),
    ).toBe("2026-03-01");
    expect(
      latestOccurrenceOn(weekly("UTC", "2026-03-01", 1), new Date("2026-03-02T00:00:00Z")),
    ).toBe("2026-03-02");
  });

  it("judges the weekday in the rule's zone, not in UTC", () => {
    // Sunday 22:00 UTC is already Monday 07:00 in Tokyo.
    const now = new Date("2026-03-01T22:00:00Z");
    expect(latestOccurrenceOn(weekly("Asia/Tokyo", "2026-01-01", 1), now)).toBe(
      "2026-03-02",
    );
    expect(latestOccurrenceOn(weekly("UTC", "2026-01-01", 1), now)).toBe(
      "2026-02-23",
    );
  });
});

