import { describe, expect, it } from "vitest";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";

const ORG = "01HZX3K9M2V7Q8R4T6Y1B5N0CD";
const PROJECT = "01HZX3K9M2V7Q8R4T6Y1B5N0CE";
const USER = "01HZX3K9M2V7Q8R4T6Y1B5N0CF";

const valid = {
  orgId: ORG,
  projectId: PROJECT,
  title: "Daily triage",
  cadence: "daily",
  timezone: "Europe/Berlin",
  startsOn: "2026-03-05",
};

describe("schemas/recurring-issue", () => {
  it("applies the defaults for priority, assignee and weekday", () => {
    expect(createRecurringIssueSchema.parse(valid)).toEqual({
      ...valid,
      priority: "none",
      assigneeId: null,
      weekday: null,
    });
  });

  it("accepts a weekly rule with a weekday and an assignee", () => {
    const parsed = createRecurringIssueSchema.parse({
      ...valid,
      title: "Monday planning",
      cadence: "weekly",
      weekday: 1,
      priority: "high",
      assigneeId: USER,
    });
    expect(parsed).toMatchObject({ cadence: "weekly", weekday: 1, assigneeId: USER });
  });

  it("refuses a weekly rule without a weekday and a daily rule with one", () => {
    expect(
      createRecurringIssueSchema.safeParse({ ...valid, cadence: "weekly" }).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({ ...valid, weekday: 3 }).success,
    ).toBe(false);
  });

  it("keeps the weekday within the ISO range", () => {
    const weekly = { ...valid, cadence: "weekly" };
    for (const weekday of [0, 8, 1.5]) {
      expect(
        createRecurringIssueSchema.safeParse({ ...weekly, weekday }).success,
        String(weekday),
      ).toBe(false);
    }
    for (const weekday of [1, 7]) {
      expect(
        createRecurringIssueSchema.safeParse({ ...weekly, weekday }).success,
        String(weekday),
      ).toBe(true);
    }
  });

  it("bounds the title to 3-180 characters", () => {
    expect(createRecurringIssueSchema.safeParse({ ...valid, title: "ab" }).success).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({ ...valid, title: "a".repeat(180) }).success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse({ ...valid, title: "a".repeat(181) }).success,
    ).toBe(false);
  });

  it("refuses an unknown time zone", () => {
    for (const timezone of ["Mars/Olympus_Mons", "", "CET-1", "+01:00"]) {
      expect(
        createRecurringIssueSchema.safeParse({ ...valid, timezone }).success,
        timezone,
      ).toBe(false);
    }
  });

  it("refuses a start date that is not a real calendar day", () => {
    for (const startsOn of ["2026-02-30", "2026-13-01", "2026-3-5", "tomorrow", ""]) {
      expect(
        createRecurringIssueSchema.safeParse({ ...valid, startsOn }).success,
        startsOn,
      ).toBe(false);
    }
  });

  it("validates ids like the other schemas do", () => {
    expect(createRecurringIssueSchema.safeParse({ ...valid, orgId: "acme" }).success).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({ ...valid, assigneeId: "not-a-ulid" }).success,
    ).toBe(false);
  });
});

