    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("requires an active member as the assignee", async () => {
    const t = await createTenant("recassignee");

    const stranger = await userRepo.insertUser({
      email: "stranger@recassignee.test",
      name: "Stranger",
      passwordHash: "seed",
    });
    await expect(
      recurringIssueService.createRecurringIssue(
        t.actors.member,
        ruleInput(t, { assigneeId: stranger.id }),
      ),
    ).rejects.toThrow();

    const removed = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (removed === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(t.org.id, removed.id);
    await expect(
      recurringIssueService.createRecurringIssue(
        t.actors.member,
        ruleInput(t, { assigneeId: t.userIds.viewer }),
      ),
    ).rejects.toThrow();

    expect(
      await recurringIssueService.listRecurringIssues(t.actors.member, t.org.id),
    ).toEqual([]);
  });

  it("caps the rules per plan, counting paused ones", async () => {
    const starter = await createTenant("recstarter", "starter");
    const first = await recurringIssueService.createRecurringIssue(
      starter.actors.member,
      ruleInput(starter, { title: "Rule one" }),
    );
    await recurringIssueService.createRecurringIssue(
      starter.actors.member,
      ruleInput(starter, { title: "Rule two" }),
    );
    await recurringIssueService.createRecurringIssue(
      starter.actors.member,
      ruleInput(starter, { title: "Rule three" }),
    );
    await recurringIssueService.setRecurringIssuePaused(starter.actors.member, {
      orgId: starter.org.id,
      recurringIssueId: first.id,
      paused: true,
    });

    await expect(
      recurringIssueService.createRecurringIssue(
        starter.actors.member,
        ruleInput(starter, { title: "Rule four" }),
      ),
    ).rejects.toThrow();
    expect(
      await recurringIssueService.listRecurringIssues(
        starter.actors.member,
        starter.org.id,
      ),
    ).toHaveLength(3);
  });

  it("allows no rules at all on the free plan", async () => {
    const free = await createTenant("recfree", "free");
    await expect(
      recurringIssueService.createRecurringIssue(free.actors.member, ruleInput(free)),
    ).rejects.toThrow();
  });

  it("never lets concurrent creations slip past the cap", async () => {
    const starter = await createTenant("recracing", "starter");
    const results = await Promise.allSettled(
      Array.from({ length: 6 }, (_, index) =>
        recurringIssueService.createRecurringIssue(
          starter.actors.member,
          ruleInput(starter, { title: `Racer ${index}` }),
        ),
      ),
    );

    expect(results.filter((result) => result.status === "fulfilled")).toHaveLength(3);
    expect(
      await recurringIssueService.listRecurringIssues(
        starter.actors.member,
        starter.org.id,
      ),
    ).toHaveLength(3);
  });
});

describe("services/recurring-issue-service setRecurringIssuePaused", () => {
  it("pauses and resumes a rule", async () => {
    const t = await createTenant("recpause");
    const rule = await recurringIssueService.createRecurringIssue(
      t.actors.member,
      ruleInput(t),
    );

    const paused = await recurringIssueService.setRecurringIssuePaused(t.actors.member, {
      orgId: t.org.id,
      recurringIssueId: rule.id,
      paused: true,
    });
    expect(paused.paused).toBe(true);

    const resumed = await recurringIssueService.setRecurringIssuePaused(t.actors.member, {
      orgId: t.org.id,
      recurringIssueId: rule.id,
      paused: false,
    });
    expect(resumed.paused).toBe(false);
  });

  it("refuses another organization's id, an unknown rule and a viewer", async () => {
    const t = await createTenant("recpauseguard");
    const rule = await recurringIssueService.createRecurringIssue(
      t.actors.member,
      ruleInput(t),
    );

    await expect(
      recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
        orgId: t.org.id,
        recurringIssueId: rule.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    // A rule of another organization does not exist as far as this actor sees.
    await expect(
      recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
        orgId: tenant.org.id,
        recurringIssueId: rule.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      recurringIssueService.setRecurringIssuePaused(t.actors.viewer, {
        orgId: t.org.id,
        recurringIssueId: rule.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

describe("services/recurring-issue-service listRecurringIssues", () => {
  it("lists an organization's rules in creation order", async () => {
    const t = await createTenant("reclist");
    for (const title of ["Third try", "Alpha", "Zulu"]) {
      await recurringIssueService.createRecurringIssue(
        t.actors.member,
        ruleInput(t, { title }),
      );
    }

    const listed = await recurringIssueService.listRecurringIssues(
      t.actors.viewer,
      t.org.id,
    );
    expect(listed.map((rule) => rule.title)).toEqual(["Third try", "Alpha", "Zulu"]);
  });

  it("refuses another organization", async () => {
    await expect(
      recurringIssueService.listRecurringIssues(
        tenant.actors.member,
        (await createTenant("reclistother")).org.id,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

