/**
 * Files one ordinary issue per rule for its latest started occurrence, as the
 * rule's creator, and leaves the rule alone whenever creation is refused for a
 * reason that may pass.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { drain, enqueue, resetQueue } from "@/server/jobs";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
});

afterAll(() => {
  cleanup();
});

/** Stores a rule through the repository, skipping the service's plan quota. */
async function addRule(
  t: Tenant,
  overrides: Partial<CreateRecurringIssueInput> = {},
  createdBy: UserId = t.userIds.member,
) {
  const input = createRecurringIssueSchema.parse({
    orgId: t.org.id,
    projectId: t.project.id,
    title: "Daily triage",
    cadence: "daily",
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...overrides,
  });
  const rule = await recurringIssueRepo.insertRecurringIssueWithinLimit(
    input,
    createdBy,
    Number.POSITIVE_INFINITY,
  );
  if (rule === null) throw new Error("rule not stored");
  return rule;
}

async function reload(t: Tenant, id: string) {
  const rule = await recurringIssueRepo.findRecurringIssueById(t.org.id, id);
  if (rule === null) throw new Error("rule vanished");
  return rule;
}

async function issuesOf(t: Tenant) {
  const page = await issueRepo.listIssues({
    orgId: t.org.id,
    projectId: t.project.id,
    limit: 100,
  });
  return page.items;
}

const MARCH_5 = new Date("2026-03-05T09:00:00Z");

describe("runRecurringIssueJob", () => {
  it("files the latest occurrence as a backlog issue and advances the rule", async () => {
    const t = await createTenant("recjob");
    const rule = await addRule(t, {
      priority: "urgent",
      assigneeId: t.userIds.admin,
    });

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result).toMatchObject({ kind: "recurring-issues", processed: 1, failed: 0 });
    const [issue, ...rest] = await issuesOf(t);
    expect(rest).toEqual([]);
    expect(issue).toMatchObject({
      title: "Daily triage (2026-03-05)",
      projectId: t.project.id,
      status: "backlog",
      priority: "urgent",
      description: null,
      dueAt: null,
      labelIds: [],
      assigneeId: t.userIds.admin,
      authorId: t.userIds.member,
    });
    expect((await reload(t, rule.id)).lastOccurrenceOn).toBe("2026-03-05");
  });

  it("creates nothing when run again for the same moment", async () => {
    const t = await createTenant("recjobtwice");
    await addRule(t);

    await runRecurringIssueJob(MARCH_5);
    const again = await runRecurringIssueJob(MARCH_5);

    expect(again.processed).toBe(0);
    expect(await issuesOf(t)).toHaveLength(1);
  });

  it("runs strictly one at a time, so overlapping runs file once", async () => {
    const t = await createTenant("recjobrace");
    await addRule(t);

    await Promise.all([runRecurringIssueJob(MARCH_5), runRecurringIssueJob(MARCH_5)]);

    expect(await issuesOf(t)).toHaveLength(1);
  });

  it("never back-fills: days the job missed collapse into the latest one", async () => {
    const t = await createTenant("recjobgap");
    const rule = await addRule(t, { startsOn: "2026-01-01" });
    await recurringIssueRepo.setLastOccurrenceOn(t.org.id, rule.id, "2026-03-01");

    await runRecurringIssueJob(MARCH_5);

    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Daily triage (2026-03-05)",
    ]);
  });

  it("files the next day's issue on the next day", async () => {
    const t = await createTenant("recjobnext");
    await addRule(t);

    await runRecurringIssueJob(MARCH_5);
    await runRecurringIssueJob(new Date("2026-03-06T00:00:00Z"));

    expect((await issuesOf(t)).map((issue) => issue.title).sort()).toEqual([
      "Daily triage (2026-03-05)",
      "Daily triage (2026-03-06)",
    ]);
  });

  it("does nothing before the rule starts", async () => {
    const t = await createTenant("recjobearly");
    const rule = await addRule(t, { startsOn: "2026-03-10" });

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result.processed).toBe(0);
    expect(await issuesOf(t)).toEqual([]);
    expect((await reload(t, rule.id)).lastOccurrenceOn).toBeNull();
  });

  it("counts a weekly rule's days in its own time zone", async () => {
    const t = await createTenant("recjobweekly");
    // Sunday 22:00 UTC is already Monday 07:00 in Tokyo.
    await addRule(t, {
      title: "Monday planning",
      cadence: "weekly",
      weekday: 1,
      timezone: "Asia/Tokyo",
      startsOn: "2026-01-01",
    });

    await runRecurringIssueJob(new Date("2026-03-01T22:00:00Z"));

    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Monday planning (2026-03-02)",
    ]);
  });

  it("skips paused rules", async () => {
    const t = await createTenant("recjobpaused");
    const rule = await addRule(t);
    await recurringIssueRepo.setPaused(t.org.id, rule.id, true);

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result.processed).toBe(0);
    expect(await issuesOf(t)).toEqual([]);
  });

  it("leaves a rule of an archived project unchanged until it is restored", async () => {
    const t = await createTenant("recjobarchived");
    const rule = await addRule(t);
    await projectRepo.archiveProject(t.org.id, t.project.id);

    await runRecurringIssueJob(MARCH_5);
    expect(await reload(t, rule.id)).toMatchObject({
      lastOccurrenceOn: null,
      paused: false,
    });

    await projectRepo.restoreProject(t.org.id, t.project.id);
    await runRecurringIssueJob(new Date("2026-03-09T09:00:00Z"));

    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Daily triage (2026-03-09)",
    ]);
  });

  it("pauses the rule when its creator has left the organization", async () => {
    const t = await createTenant("recjobleft");
    const rule = await addRule(t, {}, t.userIds.member);
    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    if (member === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(t.org.id, member.id);

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result.processed).toBe(0);
    expect(await issuesOf(t)).toEqual([]);
    expect(await reload(t, rule.id)).toMatchObject({
      paused: true,
      lastOccurrenceOn: null,
    });
  });

  it("pauses the rule when its creator's role no longer allows creating issues", async () => {
    const t = await createTenant("recjobdemoted");
    const rule = await addRule(t, {}, t.userIds.member);
    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    if (member === null) throw new Error("fixture member missing");
    await memberRepo.updateMemberRole(t.org.id, member.id, "viewer");

    await runRecurringIssueJob(MARCH_5);

    expect(await issuesOf(t)).toEqual([]);
    expect((await reload(t, rule.id)).paused).toBe(true);
  });

  it("files it unassigned when the assignee is no longer an active member", async () => {
    const t = await createTenant("recjobassignee");
    await addRule(t, { assigneeId: t.userIds.admin });
    const admin = await memberRepo.findMember(t.org.id, t.userIds.admin);
    if (admin === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(t.org.id, admin.id);

    await runRecurringIssueJob(MARCH_5);

    const [issue] = await issuesOf(t);
    expect(issue?.assigneeId).toBeNull();
  });

  it("leaves the rule exactly as it was when the project is at its issue quota", async () => {
    const t = await createTenant("recjobquota", "free");
    const rule = await addRule(t);
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(t.org.id, t.project.id, { title: `Seed issue ${number}` }),
        t.userIds.member,
        number,
      );
    }

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result).toMatchObject({ processed: 0, failed: 1 });
    expect(await issuesOf(t)).toHaveLength(100);
    expect(await reload(t, rule.id)).toEqual(rule);
  });

  it("publishes the same issue.created event a hand-made issue would", async () => {
    const t = await createTenant("recjobevent");
    await addRule(t, { priority: "low" });
    const seen: { actorId: UserId | null; title: string; priority: string }[] = [];
    detachers.push(
      subscribe("issue.created", (payload) => {
        seen.push({
          actorId: payload.actorId,
          title: payload.title,
          priority: payload.priority,
        });
      }),
    );

    await runRecurringIssueJob(MARCH_5);

    expect(seen).toEqual([
      { actorId: t.userIds.member, title: "Daily triage (2026-03-05)", priority: "low" },
    ]);
  });

  it("keeps going when one rule cannot be processed", async () => {
    const t = await createTenant("recjobisolation");
    // A rule stored with a zone the runtime does not know cannot be placed on
    // the calendar; it must not stop the rule behind it.
    const broken = await addRule(t, { title: "Broken rule" });
    const { getDb, recurringIssues } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    getDb()
      .update(recurringIssues)
      .set({ timezone: "Nowhere/Land" })
      .where(eq(recurringIssues.id, broken.id))
      .run();
    await addRule(t, { title: "Healthy rule" });

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result).toMatchObject({ processed: 1, failed: 1 });
    expect((await issuesOf(t)).map((issue) => issue.title)).toEqual([
      "Healthy rule (2026-03-05)",
    ]);
  });

  it("processes the rules of every organization", async () => {
    const first = await createTenant("recjobfirst");
    const second = await createTenant("recjobsecond");
    await addRule(first);
    await addRule(second);

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result.processed).toBeGreaterThanOrEqual(2);
    expect(await issuesOf(first)).toHaveLength(1);
    expect(await issuesOf(second)).toHaveLength(1);
  });

  it("runs from the job queue as the recurring-issues kind", async () => {
    const t = await createTenant("recjobqueue");
    await addRule(t, { startsOn: "2020-01-01" });

    enqueue({
      id: "recurring-issues:test",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    const [issue] = await issuesOf(t);
    expect(issue?.title).toMatch(/^Daily triage \(\d{4}-\d{2}-\d{2}\)$/);
  });
});

