    await recurringIssueRepo.setPaused(t.org.id, rule.id, true);

    const result = await runRecurringIssueJob(MARCH_5);

    expect(result.processed).toBe(0);
    expect(await issuesOf(t)).toEqual([]);
  });

  it("leaves a rule of an archived project unchanged until it is restored", async () => {
